require 'net/smtp'

# Description: Sublayer::Action responsible for sending an email using SMTP.
# This action is intended to be used for notifications or updates from AI processes directly to email.
#
# It is initialized with SMTP settings, recipients, subject, and message body.
# It returns a confirmation message if sent successfully.
#
# Example usage: When you want to send a notification or update generated by AI directly to an email address.

class EmailSendAction < Sublayer::Actions::Base
  def initialize(smtp_settings:, recipients:, subject:, body:)
    @smtp_settings = smtp_settings
    @recipients = recipients
    @subject = subject
    @body = body
  end

  def call
    send_email
  rescue StandardError => e
    error_message = "Error sending email: #{e.message}"
    Sublayer.configuration.logger.log(:error, error_message)
    raise e
  end

  private

  def send_email
    message = <<~MESSAGE_END
      From: #{@smtp_settings[:from]}
      To: #{@recipients.join(", ")}
      Subject: #{@subject}

      #{@body}
    MESSAGE_END

    Net::SMTP.start(@smtp_settings[:address], @smtp_settings[:port], @smtp_settings[:domain],
                   @smtp_settings[:user_name], @smtp_settings[:password], @smtp_settings[:authentication]) do |smtp|
      smtp.send_message message, @smtp_settings[:from], *@recipients
    end

    Sublayer.configuration.logger.log(:info, "Email sent successfully to #{@recipients.join(", ")}")
    "Email sent successfully"
  end
end
